const item = $input.first().json;
const cierres = (item.data && Array.isArray(item.data.cierres)) ? item.data.cierres : [];
const listos = cierres.filter((c) => c.estado === 'LISTO_PARA_PUBLICAR');
return listos.map((c) => ({ json: c }));

function formatMoney(v) {
  if (v === null || v === undefined || v === '') return 'N/D';
  const n = Number(v);
  if (Number.isNaN(n)) return String(v);
  const fixed = n.toFixed(2);
  const partes = fixed.split('.');
  const conMiles = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return 'Bs ' + conMiles + ',' + partes[1];
}

function formatFecha(iso) {
  if (!iso) return 'N/D';
  const partes = String(iso).split('-');
  if (partes.length !== 3) return String(iso);
  return partes[2] + '/' + partes[1] + '/' + partes[0];
}

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const allItems = $input.all();
let batch = null;
const detallesArchivo = [];

for (const it of allItems) {
  const d = it.json && it.json.data;
  if (d && Array.isArray(d.cierres)) {
    batch = d;
  } else if (d) {
    detallesArchivo.push(d);
  }
}

const cierres = batch ? batch.cierres : [];
const total = batch ? batch.total_cierres_rango : cierres.length;
const listos = cierres.filter((c) => c.estado === 'LISTO_PARA_PUBLICAR');
const revision = cierres.filter((c) => c.estado === 'ERROR_REVISAR');
const hayRevision = revision.length > 0;
const otros = total - listos.length - revision.length;

function detalleDe(cierre) {
  return detallesArchivo.find((d) => d.sha256_origen === cierre.hash) || {};
}

const bannerEstilo = hayRevision
  ? 'background:#fbedde;border:1px solid #a66423;color:#8a4e13;'
  : 'background:#e3f2e9;border:1px solid #2f7d5a;color:#2f7d5a;';

const headline = hayRevision
  ? listos.length + ' de ' + total + ' cierres cuadrados · ' + revision.length + (revision.length === 1 ? ' requiere revision' : ' requieren revision')
  : total + ' de ' + total + ' cierres cuadrados y listos para publicar';

const asideOtros = otros > 0
  ? '<div style="font-size:12.5px;color:#8a978f;margin-top:4px;">' + otros + ' dia(s) del rango sin accion (ya procesado o sin archivo).</div>'
  : '';

const bloqueoBlock = hayRevision
  ? '<div style="margin-top:12px;background:#fbedde;border:1px solid #a66423;color:#8a4e13;border-radius:8px;padding:12px 14px;font-size:13.5px;line-height:1.7;">' +
    '<div style="font-weight:700;font-size:14.5px;">⚠️ PUBLICACION BLOQUEADA</div>' +
    '<div>' + revision.length + (revision.length === 1 ? ' cierre requiere' : ' cierres requieren') + ' revision antes de continuar.</div>' +
    '<div>Decision: Dejar pendiente para revision</div>' +
    '</div>'
  : '';

function campo(etiqueta, valor) {
  return '<div style="display:flex;justify-content:space-between;gap:14px;padding:3px 0;font-size:13.5px;">' +
    '<span style="color:#54655f;">' + etiqueta + '</span>' +
    '<span style="font-weight:600;color:#182722;">' + valor + '</span>' +
    '</div>';
}

function tarjetaCuadrado(c) {
  const d = detalleDe(c);
  const sapLinea = (d.sap_validacion === 'OK')
    ? '<div style="margin-top:8px;font-weight:600;color:#2f7d5a;">SAP validado correctamente</div>'
    : '<div style="margin-top:8px;font-weight:600;">Validacion SAP: ' + escapeHtml(d.sap_validacion || 'N/D') + '</div>';
  return '<div style="border:1px solid #dbe3dd;border-left:5px solid #2f7d5a;border-radius:8px;padding:14px 16px;margin-bottom:12px;">' +
    '<div style="font-weight:700;font-size:15px;margin-bottom:10px;">' + formatFecha(c.fecha) + ' · CIERRE CUADRADO</div>' +
    campo('Total conciliado', formatMoney(d.universo_ajustado)) +
    campo('Diferencia', formatMoney(c.diferencia)) +
    campo('Bloqueos', c.blockers) +
    campo('Cargo', formatMoney(d.cargo)) +
    campo('Haber', formatMoney(d.haber)) +
    campo('Diferencia del asiento', formatMoney(d.diferencia_asiento)) +
    sapLinea +
    '</div>';
