  }];
}

return [{ json: parsed }];

const base = $('PARAMETROS - Rango (desde formulario)').first().json;
const inicio = base.fecha_inicio;
const fin = base.fecha_fin;

function parseISO(s) {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}
function pad(n) {
  return String(n).padStart(2, '0');
}

const start = parseISO(inicio);
const end = parseISO(fin);

const items = [];
for (let dt = new Date(start); dt <= end; dt.setUTCDate(dt.getUTCDate() + 1)) {
  const y = dt.getUTCFullYear();
  const m = pad(dt.getUTCMonth() + 1);
  const d = pad(dt.getUTCDate());
  const fecha_iso = `${y}-${m}-${d}`;
  const fecha_archivo = `${d}-${m}-${y}`;
  const nombre_archivo = `CIERRE ${fecha_archivo}.xlsm`;
  items.push({ json: { fecha_iso, fecha_archivo, nombre_archivo } });
}

return items;

